"""Keep generated integration text intact during personal Markdown formatting."""

import shlex
import shutil
from pathlib import Path

import pytest

from dotf import ops


@pytest.mark.parametrize("newline", ["\n", "\r\n"])
def test_formatter_preserves_beads_block_and_formats_personal_text(tmp_path: Path, newline: str) -> None:
    """A formatting pass must not make the generator consider its block stale."""
    path = tmp_path / "AGENTS.md"
    block = (
        "<!-- BEGIN BEADS CODEX SETUP: generated by bd setup codex -->\n"
        "##  Generated instructions\n\nDo not reformat this block.\n"
        "<!-- END BEADS CODEX SETUP -->"
    )
    block = block.replace("\n", newline)
    path.write_text(block + "\n\n#   Personal preferences\n")
    formatter = shutil.which("prettier")
    assert formatter is not None
    # The machine's ignore files exclude temporary directories. Exercise the
    # real formatter rather than its ignored-file passthrough behavior.
    wrapper = tmp_path / "prettier-test"
    wrapper.write_text("#!/bin/sh\nexec " + shlex.quote(formatter) + ' --ignore-path /dev/null "$@"\n')
    wrapper.chmod(0o700)
    ops._format_agent_markdown(path, str(wrapper))
    result = path.read_bytes().decode()
    assert block in result
    assert "# Personal preferences\n" in result
    ops._format_agent_markdown(path, str(wrapper))
    assert path.read_bytes().decode() == result


def test_formatter_leaves_file_intact_on_failure(tmp_path: Path) -> None:
    """Failed formatting must not truncate instructions."""
    path = tmp_path / "AGENTS.md"
    path.write_text("# Original instructions\n")
    formatter = tmp_path / "failing-formatter"
    formatter.write_text("#!/bin/sh\nprintf partial-output\nexit 1\n")
    formatter.chmod(0o700)
    ops._format_agent_markdown(path, str(formatter))
    assert path.read_text() == "# Original instructions\n"
